def bucket_timestamp(ts, bucket_seconds=300):
    # Bucket a unix timestamp to the start of its time bucket.
    return (int(ts) // bucket_seconds) * bucket_seconds


def safe_float(value, default=0.0):
    # Convert to float safely, returning default if conversion fails.
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def safe_int(value, default=0):
    # Convert to int safely, returning default if conversion fails.
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def parse_time(value):
    # Parse timestamp; if not possible, treat as None.
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value)
        except ValueError:
            return None
    return None


# ---- Input collection (exactly once each) ----
metrics = ops.query_metrics(service="checkout", window="6h")
logs = ops.query_logs(service="checkout", severity="error", window="6h")
deployment = ops.latest_deployment(repository="shop/checkout")
config = ops.read_deployment(cluster="prod-eu", namespace="checkout")


# ---- Normalize metrics ----
# Expected metrics dictionary: {metric_name: [ {timestamp, value}, ... ] } or {metric_name: {values: [...]}}
metric_names = ["error_rate", "p99_latency_ms", "cpu_usage_percent", "memory_usage_percent"]

# Make a safe copy of metrics if missing or not dict.
if not isinstance(metrics, dict):
    metrics = {}

normalized_metrics = {}
for name in metric_names:
    raw_series = metrics.get(name, [])
    series = []
    if isinstance(raw_series, list):
        for item in raw_series:
            if isinstance(item, dict):
                ts = parse_time(item.get("timestamp"))
                val = safe_float(item.get("value"))
                if ts is not None:
                    series.append((ts, val))
            elif isinstance(item, (list, tuple)) and len(item) >= 2:
                ts = parse_time(item[0])
                val = safe_float(item[1])
                if ts is not None:
                    series.append((ts, val))
    elif isinstance(raw_series, dict):
        # Assume keys are timestamps and values are numbers.
        for k, v in raw_series.items():
            ts = parse_time(k)
            val = safe_float(v)
            if ts is not None:
                series.append((ts, val))
    normalized_metrics[name] = series


# ---- Normalize logs ----
# Expected logs: list of dicts with fields: timestamp, message, error_type, pod, trace_id
if not isinstance(logs, list):
    logs = []

normalized_logs = []
for entry in logs:
    if not isinstance(entry, dict):
        continue
    ts = parse_time(entry.get("timestamp"))
    if ts is None:
        continue
    message = entry.get("message", "") or ""
    error_type = entry.get("error_type", "unknown") or "unknown"
    pod = entry.get("pod", "") or "unknown"
    trace_id = entry.get("trace_id", "") or ""
    normalized_logs.append({
        "timestamp": ts,
        "message": str(message),
        "error_type": str(error_type),
        "pod": str(pod),
        "trace_id": str(trace_id)
    })


# ---- Normalize deployment ----
if not isinstance(deployment, dict):
    deployment = {}
deployment_info = {
    "commit": deployment.get("commit"),
    "version": deployment.get("version"),
    "deployed_at": parse_time(deployment.get("deployed_at")),
    "status": deployment.get("status", "unknown"),
    "author": deployment.get("author", "unknown")
}


# ---- Normalize config ----
if not isinstance(config, dict):
    config = {}
config_actual = {
    "feature_flag": config.get("feature_flags", {}).get("new_checkout") if isinstance(config.get("feature_flags"), dict) else None,
    "log_level": config.get("log_level"),
    "replicas": config.get("replicas")
}


# ---- Time-bucket aggregation for metrics ----
bucket_size = 300  # 5 minutes
bucketed_metrics = {}
for name, series in normalized_metrics.items():
    buckets = {}
    counts = {}
    for ts, val in series:
        b = bucket_timestamp(ts, bucket_size)
        if b not in buckets:
            buckets[b] = 0.0
            counts[b] = 0
        buckets[b] += val
        counts[b] += 1
    # Compute average per bucket
    aggregated = {}
    for b in sorted(buckets.keys()):
        if counts[b] > 0:
            avg = buckets[b] / counts[b]
            aggregated[b] = avg
        else:
            aggregated[b] = 0.0
    bucketed_metrics[name] = aggregated


# ---- Count errors per bucket and group by error type ----
error_buckets = {}
error_types = {}
for log in normalized_logs:
    b = bucket_timestamp(log["timestamp"], bucket_size)
    if b not in error_buckets:
        error_buckets[b] = 0
    error_buckets[b] += 1
    et = log["error_type"]
    if et not in error_types:
        error_types[et] = 0
    error_types[et] += 1

# Identify top error types
sorted_error_types = sorted(error_types.items(), key=lambda x: x[1], reverse=True)
top_error_types = sorted_error_types[:5]  # top 5

# ---- Deployment correlation ----
relevant_buckets = []
deploy_time = deployment_info.get("deployed_at")
if deploy_time is not None:
    deploy_bucket = bucket_timestamp(deploy_time, bucket_size)
    # Get metrics in window around deployment: -1h to +2h
    window_start = deploy_bucket - 12 * 300  # -1h
    window_end = deploy_bucket + 24 * 300   # +2h
    # Collect buckets in that range
    all_bucket_times = set(bucketed_metrics.get("error_rate", {}).keys())
    all_bucket_times.update(error_buckets.keys())
    for b in sorted(all_bucket_times):
        if window_start <= b <= window_end:
            relevant_buckets.append(b)

# Pre-deployment vs post-deployment metrics
pre_metrics = []
post_metrics = []
if deploy_time is not None:
    pre_start = deploy_time - 7200  # 2h before
    pre_end = deploy_time - 300     # just before deploy (minus 5min)
    post_start = deploy_time + 300  # 5min after
    post_end = deploy_time + 7200   # 2h after
    for b, val in bucketed_metrics.get("error_rate", {}).items():
        if pre_start <= b < deploy_time:
            pre_metrics.append(val)
        if post_start <= b <= post_end:
            post_metrics.append(val)

pre_avg_error = sum(pre_metrics) / len(pre_metrics) if pre_metrics else None
post_avg_error = sum(post_metrics) / len(post_metrics) if post_metrics else None


# ---- Configuration-drift check ----
config_drift = False
drift_reasons = []
if config_actual["feature_flag"] is None:
    drift_reasons.append("feature_flag missing")
    config_drift = True
else:
    expected_flag = True  # expected from deployment info
    if config_actual["feature_flag"] != expected_flag:
        drift_reasons.append("feature_flag mismatch")
        config_drift = True
if "log_level" not in config_actual or config_actual["log_level"] is None:
    drift_reasons.append("log_level missing")
    config_drift = True
else:
    acceptable_levels = ["info", "debug", "warn", "error"]
    if config_actual["log_level"] not in acceptable_levels:
        drift_reasons.append("log_level unexpected")
        config_drift = True
if config_actual["replicas"] is None:
    drift_reasons.append("replicas missing")
    config_drift = True
else:
    replicas = safe_int(config_actual["replicas"])
    if replicas < 3 or replicas > 10:
        drift_reasons.append("replicas out of range")
        config_drift = True


# ---- Threshold evaluation ----
# Define thresholds
thresholds = {
    "error_rate": 0.05,       # 5% errors
    "p99_latency_ms": 500.0,  # 500 ms
    "cpu_usage_percent": 90.0,
    "memory_usage_percent": 85.0
}

threshold_violations = []
for name, series in bucketed_metrics.items():
    if name in thresholds:
        threshold = thresholds[name]
        for b, val in series.items():
            if val > threshold:
                threshold_violations.append({"metric": name, "bucket": b, "value": val, "threshold": threshold})

# Count buckets with any violation
total_buckets = set()
for v in threshold_violations:
    total_buckets.add(v["bucket"])

# ---- Evidence-table construction ----
evidence_table = []
# Add metric evidence
evidence_table.append({"type": "metric", "source": "metrics", "detail": "error_rate"})
# Add top error types
evidence_table.append({"type": "log", "source": "logs", "detail": "top_error_types"})
# Add deployment info
evidence_table.append({"type": "deployment", "source": "deployment", "detail": "deployment"})
# Add config drift evidence
evidence_table.append({"type": "config", "source": "config", "detail": "config_drift"})
# Add specifics for top error types
for et, count in top_error_types:
    evidence_table.append({"type": "error", "error_type": et, "count": count})


# ---- Confidence scoring ----
confidence = 0.0
# Start with 50 baseline confidence
confidence += 50.0
# Add up to 20 for data coverage: have metrics and logs
if normalized_metrics.get("error_rate"):
    confidence += 10.0
else:
    confidence -= 10.0
if normalized_logs:
    confidence += 5.0
else:
    confidence -= 5.0
# Add up to 15 if deployment info present
if deployment_info.get("deployed_at") is not None:
    confidence += 10.0
else:
    confidence += 0.0
# Add up to 15 if config present
if config_actual.get("feature_flag") is not None:
    confidence += 5.0
else:
    confidence += 0.0
# Penalize if many threshold violations
if total_buckets:
    # Each violating bucket subtracts 2, max 10
    penalty = min(10.0, len(total_buckets) * 2.0)
    confidence -= penalty
# Penalize config drift
if config_drift:
    confidence -= 10.0
# Clamp between 0 and 100
confidence = max(0.0, min(100.0, confidence))


# ---- Release-gate decisions ----
release_ready = True
gates = []

# Gate 1: No critical threshold violations in last hour?
now = max([ts for series in normalized_metrics.values() for ts, _ in series] + [log["timestamp"] for log in normalized_logs] + [0])
last_hour_start = now - 3600
recent_violations = [v for v in threshold_violations if v["bucket"] >= last_hour_start]
if recent_violations:
    release_ready = False
    gates.append({"name": "recent_metric_violations", "pass": False, "details": "Violations in last hour"})
else:
    gates.append({"name": "recent_metric_violations", "pass": True})

# Gate 2: Error rate trend not increasing?
if deploy_time is not None and pre_avg_error is not None and post_avg_error is not None:
    if post_avg_error > pre_avg_error * 2 and post_avg_error > thresholds["error_rate"]:
        release_ready = False
        gates.append({"name": "post_deploy_error_spike", "pass": False})
    else:
        gates.append({"name": "post_deploy_error_spike", "pass": True})
else:
    gates.append({"name": "post_deploy_error_spike", "pass": True, "details": "Insufficient data"})

# Gate 3: No severe error types?
severe_types = ["database_connection", "payment_timeout", "null_pointer"]
severe_found = False
for et, _ in top_error_types:
    if et in severe_types:
        severe_found = True
        break
if severe_found:
    release_ready = False
    gates.append({"name": "severe_error_types", "pass": False, "details": "Found severe error types"})
else:
    gates.append({"name": "severe_error_types", "pass": True})

# Gate 4: No config drift
if config_drift:
    release_ready = False
    gates.append({"name": "config_drift", "pass": False, "details": " ".join(drift_reasons)})
else:
    gates.append({"name": "config_drift", "pass": True})

# Gate 5: Deployment status is successful
if deployment_info.get("status") not in ["success", "live", "healthy"]:
    release_ready = False
    gates.append({"name": "deployment_status", "pass": False})
else:
    gates.append({"name": "deployment_status", "pass": True})

# ---- Structured report ----
report = {
    "summary": "Release readiness analysis for checkout service",
    "deployment": deployment_info,
    "config_drift": {
        "drift": config_drift,
        "reasons": drift_reasons
    },
    "metrics_summary": {
        "error_rate": {
            "buckets": len(bucketed_metrics.get("error_rate", {})),
            "max": max(bucketed_metrics.get("error_rate", {}).values()) if bucketed_metrics.get("error_rate") else None,
            "avg": sum(bucketed_metrics.get("error_rate", {}).values()) / len(bucketed_metrics.get("error_rate", {})) if bucketed_metrics.get("error_rate") else None
        },
        "p99_latency_ms": {
            "buckets": len(bucketed_metrics.get("p99_latency_ms", {})),
            "max": max(bucketed_metrics.get("p99_latency_ms", {}).values()) if bucketed_metrics.get("p99_latency_ms") else None
        }
    },
    "error_logs": {
        "count": len(normalized_logs),
        "top_types": top_error_types
    },
    "threshold_violations": threshold_violations[:10],  # Limit to avoid huge output
    "evidence": evidence_table,
    "confidence": round(confidence, 2),
    "gates": gates,
    "release_ready": release_ready
}

# Ensure final result is the data structure
result = report
